class Partition:
    def __init__(self, pieces, total):
        self.pieces = pieces
        self.total = total
        self.used = [False] * len(pieces)

    def dfs(self, target):
        return self._dfs(1, 0, target, 0, self.total // target)

    def _dfs(self, step, total, target, last, need):
        if need == 0:
            return total == 0
        for index in range(last, len(self.pieces)):
            if self.used[index] or total + self.pieces[index] > target:
                continue
            self.used[index] = True
            next_total = total + self.pieces[index]
            if next_total == target:
                found = self._dfs(step + 1, 0, target, 0, need - 1)
            else:
                found = self._dfs(step + 1, next_total, target, index + 1, need)
            self.used[index] = False
            if found:
                return True
        return False

