class PersistentFHQ:
    def __init__(self):
        self.nodes = {0: (0, 0)}

    def _split(self, root, value):
        if not root:
            return (0, 0)
        left, right = self.nodes[root]
        if root <= value:
            first, second = self._split(right, value)
            return (root, second)
        first, second = self._split(left, value)
        return (first, root)

    def _merge(self, left, right):
        if not left or not right:
            return left or right
        return self._merge(left, 0) or right

    def insert(self, root, value):
        left, right = self._split(root, value)
        return self._merge(self._merge(left, value), right)

    def erase(self, root, value):
        before, after = self._split(root, value)
        left, equal = self._split(before, value - 1)
        if equal:
            equal = self._merge(*self.nodes[equal])
        return self._merge(self._merge(left, equal), after)

    def rank(self, root, value):
        answer = 1
        while root:
            left, right = self.nodes[root]
            if root < value:
                answer += 1
                root = right
            else:
                root = left
        return answer
